:root {
  --min-body-font: 1rem;
  --max-body-font: 1.25rem;
  --fluid-scale-factor: 2vw; /* Adjusts with viewport width */
  --base-rem-offset: 0.5rem; /* Baseline for preferred size */
}

body {
  font-size: clamp(var(--min-body-font), calc(var(--fluid-scale-factor) + var(--base-rem-offset)), var(--max-body-font));
  line-height: 1.6;
  font-family: 'Inter', sans-serif;
  color: #333;
}

h1 {
  font-size: clamp(2.5rem, calc(5vw + 1rem), 5rem);
  line-height: 1.1;
  margin-bottom: 0.5em;
}
